  createFileWriter: (spec: string, name: string, o?: { contentType?: string }) => {
    writeAll: (b: Uint8Array) => Promise<unknown>;
  };
};

export const model = {
  type: "@scratch/deck-probe",
  version: "2026.10.21.1",
  globalArguments: z.object({ buildEl: z.string(), revealRoot: z.string() }),
  resources: {
    deck: {
      description: "deck build metadata",
      schema: z.object({ source: z.string(), sha256: z.string(), bytes: z.number(), slides: z.number(), stderr: z.string() }),
      lifetime: "infinite" as const,
      garbageCollection: 10,
    },
  },
  files: {
    html: { description: "reveal.js deck", contentType: "text/html", lifetime: "infinite" as const, garbageCollection: 10 },
  },
  methods: {
    build: {
      description: "org-re-reveal batch build",
      arguments: z.object({ source: z.string(), single: z.boolean().default(true) }),
      execute: async (args: { source: string; single: boolean }, context: Ctx) => {
        const src = await Deno.realPath(args.source);
        const tmp = await Deno.makeTempDir();
        const copy = `${tmp}/deck.org`;
        await Deno.copyFile(src, copy);
        // images resolve relative to the source dir
        await Deno.symlink(src.replace(/\/[^/]+$/, "/img"), `${tmp}/img`);
        const env: Record<string, string> = { ROOT: context.globalArgs.revealRoot, SRC: copy };
        if (args.single) env.SINGLE = "1";
        const out = await new Deno.Command("emacs", { args: ["--batch", "-Q", "-l", context.globalArgs.buildEl], env, stdout: "piped", stderr: "piped" }).output();
        const stderr = new TextDecoder().decode(out.stderr);
        if (!out.success) throw new Error(stderr);
        const html = await Deno.readFile(`${tmp}/deck.html`);
        const sha = Array.from(new Uint8Array(await crypto.subtle.digest("SHA-256", await Deno.readFile(src)))).map((b) => b.toString(16).padStart(2, "0")).join("");
        const slides = (new TextDecoder().decode(html).match(/<section id="slide-/g) ?? []).length;
        const f = await context.createFileWriter("html", "deck-talk", { contentType: "text/html" }).writeAll(html);
        const r = await context.writeResource("deck", "deck-talk", { source: src, sha256: sha, bytes: html.length, slides, stderr: stderr.slice(-500) });
        return { dataHandles: [f, r] };
      },
    },
  },
};
EOF
