// SPDX-License-Identifier: Apache-2.0

/**
 * Post-processing for rendered decks, the same for every engine: local files
 * become data URIs, pinned reveal.js assets are inlined or given subresource
 * integrity, and whatever still loads from elsewhere is reported.
 *
 * The rewriting never touches the bodies of `<script>`, `<style>` or
 * `<textarea>` elements. Inlined reveal.js code is full of HTML-looking
 * strings, and the reveal-markdown engine keeps its source in a textarea.
 *
 * @module
 */

import { REVEAL_CDN, REVEAL_FILES } from "./pins.ts";

/** Largest local file inlined as a data URI. */
export const MAX_INLINE_BYTES = 32 * 1024 * 1024;

const MIME: Record<string, string> = {
  png: "image/png",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  gif: "image/gif",
  svg: "image/svg+xml",
  webp: "image/webp",
  avif: "image/avif",
  bmp: "image/bmp",
  ico: "image/x-icon",
  mp4: "video/mp4",
  webm: "video/webm",
  ogv: "video/ogg",
  mp3: "audio/mpeg",
  ogg: "audio/ogg",
  wav: "audio/wav",
  css: "text/css",
  woff: "font/woff",
  woff2: "font/woff2",
  ttf: "font/ttf",
};

/** Attributes that load a resource. */
const RESOURCE_ATTRS = [
  "src",
  "data-src",
  "poster",
  "data-background",
  "data-background-image",
  "data-background-video",
];

/** Elements whose body must not be rewritten. */
const OPAQUE = /<(script|style|textarea)\b([^>]*)>([\s\S]*?)<\/\1\s*>/gi;

/**
 * Apply `fn` to the markup of `html` only, leaving the bodies of script, style
 * and textarea elements untouched. Their opening tags are markup and are
 * passed to `fn` (as part of the surrounding text).
 */
export function mapMarkup(html: string, fn: (markup: string) => string): string {
  let out = "";
  let last = 0;
  for (const m of html.matchAll(OPAQUE)) {
    const openEnd = m.index + m[0].indexOf(">") + 1;
    const bodyEnd = m.index + m[0].length - m[0].match(/<\/[^>]*>$/)![0].length;
    out += fn(html.slice(last, openEnd));
    out += html.slice(openEnd, bodyEnd);
    last = bodyEnd;
  }
  return out + fn(html.slice(last));
}

function decodeAttr(v: string): string {
  return v.replace(/&amp;/g, "&").replace(/&quot;/g, '"').replace(/&#39;/g, "'");
}

/** True for a reference to a local file rather than a URL or a fragment. */
export function isLocalPath(ref: string): boolean {
  if (ref === "" || ref.startsWith("#")) return false;
  if (/^file:/i.test(ref)) return true;
  return !/^[a-z][a-z0-9+.-]*:/i.test(ref) && !ref.startsWith("//");
}

function localPath(ref: string, baseDir: string): string {
  let p = ref.replace(/^file:(\/\/)?/i, "");
  p = p.split(/[?#]/)[0];
  try {
    p = decodeURIComponent(p);
  } catch {
    // Keep the raw path when it is not valid percent-encoding.
  }
  return p.startsWith("/") ? p : `${baseDir}/${p}`;
}

function mimeFor(path: string): string | null {
  const ext = path.slice(path.lastIndexOf(".") + 1).toLowerCase();
  return MIME[ext] ?? null;
}

function toBase64(bytes: Uint8Array): string {
  const chunk = 0x8000;
  let s = "";
  for (let i = 0; i < bytes.length; i += chunk) {
    s += String.fromCharCode(...bytes.subarray(i, i + chunk));
  }
  return btoa(s);
}

/** Read a local file as a data URI, or explain why it cannot be. */
export async function dataUri(
  ref: string,
  baseDir: string,
): Promise<{ uri: string } | { problem: string }> {
  const path = localPath(ref, baseDir);
  const mime = mimeFor(path);
  if (!mime) return { problem: `${ref}: unknown file type, left as a link` };
  let bytes: Uint8Array;
  try {
    const info = await Deno.stat(path);
    if (!info.isFile) return { problem: `${ref}: not a file` };
    if (info.size > MAX_INLINE_BYTES) {
      return {
        problem: `${ref}: ${info.size} bytes is over the ${MAX_INLINE_BYTES}-byte inline limit, left as a link`,
      };
    }
    bytes = await Deno.readFile(path);
  } catch (e) {
    if (e instanceof Deno.errors.NotFound) {
      return { problem: `${ref}: file not found` };
    }
    throw e;
  }
  return { uri: `data:${mime};base64,${toBase64(bytes)}` };
}

async function replaceAsync(
  text: string,
  re: RegExp,
  fn: (m: RegExpMatchArray) => Promise<string>,
): Promise<string> {
  const parts: string[] = [];
  let last = 0;
  for (const m of text.matchAll(re)) {
    parts.push(text.slice(last, m.index), await fn(m));
    last = m.index + m[0].length;
  }
  parts.push(text.slice(last));
  return parts.join("");
}

async function mapMarkupAsync(
  html: string,
  fn: (markup: string) => Promise<string>,
): Promise<string> {
  const segments: Array<{ markup: boolean; text: string }> = [];
  mapMarkup(html, (markup) => {
    segments.push({ markup: true, text: markup });
    return "";
  });
  // Rebuild with the opaque bodies in between, in order.
  let out = "";
  let last = 0;
  let i = 0;
  for (const m of html.matchAll(OPAQUE)) {
    const openEnd = m.index + m[0].indexOf(">") + 1;
    const bodyEnd = m.index + m[0].length - m[0].match(/<\/[^>]*>$/)![0].length;
    out += await fn(segments[i++].text);
    out += html.slice(openEnd, bodyEnd);
    last = bodyEnd;
  }
  void last;
  return out + await fn(segments[i].text);
}

/**
 * Replace local file references in resource attributes, and local
 * stylesheets, with data URIs resolved against `baseDir`. Returns the new
 * HTML and one problem per reference it could not inline.
 */
export async function inlineLocalFiles(
  html: string,
  baseDir: string,
): Promise<{ html: string; problems: string[] }> {
  const problems: string[] = [];
  const attrRe = new RegExp(
    `(\\s(?:${RESOURCE_ATTRS.join("|")})=)(["'])([^"']*)\\2`,
    "gi",
  );
  const out = await mapMarkupAsync(html, async (markup) => {
    const withAttrs = await replaceAsync(markup, attrRe, async (m) => {
      const ref = decodeAttr(m[3]);
      if (!isLocalPath(ref) || mimeFor(localPath(ref, baseDir)) === null) {
        return m[0];
      }
      const r = await dataUri(ref, baseDir);
      if ("problem" in r) {
        problems.push(r.problem);
        return m[0];
      }
      return `${m[1]}${m[2]}${r.uri}${m[2]}`;
    });
    return await replaceAsync(withAttrs, /<link\b[^>]*>/gi, async (m) => {
      const tag = m[0];
      if (!/\brel=["']?stylesheet/i.test(tag)) return tag;
      const href = tag.match(/\bhref=(["'])([^"']*)\1/i);
      if (!href || !isLocalPath(decodeAttr(href[2]))) return tag;
      const path = localPath(decodeAttr(href[2]), baseDir);
      try {
        const css = await Deno.readTextFile(path);
        return `<style>\n${css.replace(/<\/style/gi, "<\\/style")}\n</style>`;
      } catch (e) {
        if (e instanceof Deno.errors.NotFound) {
          problems.push(`${href[2]}: file not found`);
          return tag;
        }
        throw e;
      }
    });
  });
  return { html: out, problems };
}

/** The pinned `dist/` path a URL refers to, or null for any other URL. */
export function pinnedPath(url: string): string | null {
  const prefix = `${REVEAL_CDN}/`;
  if (!url.startsWith(prefix)) return null;
  const path = url.slice(prefix.length).split(/[?#]/)[0];
  return Object.hasOwn(REVEAL_FILES, path) ? path : null;
}

/**
 * Add `integrity` and `crossorigin` to every script and stylesheet loaded
 * from the pinned CDN, so the browser rejects altered files.
 */
export function addIntegrity(html: string): string {
  return mapMarkup(html, (markup) =>
    markup.replace(/<(script|link)\b[^>]*>/gi, (tag) => {
      if (/\bintegrity=/i.test(tag)) return tag;
      const url = tag.match(/\b(?:src|href)=(["'])([^"']*)\1/i)?.[2];
      const path = url ? pinnedPath(decodeAttr(url)) : null;
      if (!path) return tag;
      const attrs =
        ` integrity="sha256-${REVEAL_FILES[path]}" crossorigin="anonymous"`;
      return tag.endsWith("/>")
        ? `${tag.slice(0, -2).trimEnd()}${attrs}/>`
        : `${tag.slice(0, -1)}${attrs}>`;
    }));
}

/**
 * Inline every pinned reveal.js script and stylesheet, using `fetchFile` for
 * the verified bytes. References to unpinned CDN paths are left as links and
 * reported.
 */
export async function inlineReveal(
  html: string,
  fetchFile: (path: string) => Promise<Uint8Array>,
): Promise<{ html: string; problems: string[] }> {
  const problems: string[] = [];
  const decoder = new TextDecoder();
