  const chunk = 0x8000;
  let s = "";
  for (let i = 0; i < bytes.length; i += chunk) {
    s += String.fromCharCode(...bytes.subarray(i, i + chunk));
  }
  return btoa(s);
}

/** Read a local file as a data URI, or explain why it cannot be. */
export async function dataUri(
  ref: string,
  baseDir: string,
): Promise<{ uri: string } | { problem: string }> {
  const path = localPath(ref, baseDir);
  const mime = mimeFor(path);
  if (!mime) return { problem: `${ref}: unknown file type, left as a link` };
  let bytes: Uint8Array;
  try {
    const info = await Deno.stat(path);
    if (!info.isFile) return { problem: `${ref}: not a file` };
    if (info.size > MAX_INLINE_BYTES) {
      return {
        problem: `${ref}: ${info.size} bytes is over the ${MAX_INLINE_BYTES}-byte inline limit, left as a link`,
      };
    }
    bytes = await Deno.readFile(path);
  } catch (e) {
    if (e instanceof Deno.errors.NotFound) {
      return { problem: `${ref}: file not found` };
    }
    throw e;
  }
  return { uri: `data:${mime};base64,${toBase64(bytes)}` };
}

async function replaceAsync(
  text: string,
  re: RegExp,
  fn: (m: RegExpMatchArray) => Promise<string>,
): Promise<string> {
  const parts: string[] = [];
  let last = 0;
  for (const m of text.matchAll(re)) {
    parts.push(text.slice(last, m.index), await fn(m));
    last = m.index + m[0].length;
  }
  parts.push(text.slice(last));
  return parts.join("");
}

async function mapMarkupAsync(
  html: string,
  fn: (markup: string) => Promise<string>,
): Promise<string> {
  const segments: Array<{ markup: boolean; text: string }> = [];
  mapMarkup(html, (markup) => {
    segments.push({ markup: true, text: markup });
    return "";
  });
  // Rebuild with the opaque bodies in between, in order.
  let out = "";
  let last = 0;
  let i = 0;
  for (const m of html.matchAll(OPAQUE)) {
    const openEnd = m.index + m[0].indexOf(">") + 1;
    const bodyEnd = m.index + m[0].length - m[0].match(/<\/[^>]*>$/)![0].length;
    out += await fn(segments[i++].text);
    out += html.slice(openEnd, bodyEnd);
    last = bodyEnd;
  }
  void last;
  return out + await fn(segments[i].text);
}

/**
 * Replace local file references in resource attributes, and local
 * stylesheets, with data URIs resolved against `baseDir`. Returns the new
 * HTML and one problem per reference it could not inline.
 */
export async function inlineLocalFiles(
  html: string,
  baseDir: string,
): Promise<{ html: string; problems: string[] }> {
  const problems: string[] = [];
  const attrRe = new RegExp(
    `(\\s(?:${RESOURCE_ATTRS.join("|")})=)(["'])([^"']*)\\2`,
    "gi",
  );
  const out = await mapMarkupAsync(html, async (markup) => {
    const withAttrs = await replaceAsync(markup, attrRe, async (m) => {
      const ref = decodeAttr(m[3]);
      if (!isLocalPath(ref) || mimeFor(localPath(ref, baseDir)) === null) {
        return m[0];
      }
      const r = await dataUri(ref, baseDir);
      if ("problem" in r) {
        problems.push(r.problem);
        return m[0];
      }
      return `${m[1]}${m[2]}${r.uri}${m[2]}`;
    });
    return await replaceAsync(withAttrs, /<link\b[^>]*>/gi, async (m) => {
      const tag = m[0];
      if (!/\brel=["']?stylesheet/i.test(tag)) return tag;
      const href = tag.match(/\bhref=(["'])([^"']*)\1/i);
      if (!href || !isLocalPath(decodeAttr(href[2]))) return tag;
      const path = localPath(decodeAttr(href[2]), baseDir);
      try {
        const css = await Deno.readTextFile(path);
        return `<style>\n${css.replace(/<\/style/gi, "<\\/style")}\n</style>`;
      } catch (e) {
        if (e instanceof Deno.errors.NotFound) {
          problems.push(`${href[2]}: file not found`);
          return tag;
        }
        throw e;
      }
    });
  });
  return { html: out, problems };
}

/** The pinned `dist/` path a URL refers to, or null for any other URL. */
export function pinnedPath(url: string): string | null {
  const prefix = `${REVEAL_CDN}/`;
  if (!url.startsWith(prefix)) return null;
  const path = url.slice(prefix.length).split(/[?#]/)[0];
  return Object.hasOwn(REVEAL_FILES, path) ? path : null;
}

/**
 * Add `integrity` and `crossorigin` to every script and stylesheet loaded
 * from the pinned CDN, so the browser rejects altered files.
 */
export function addIntegrity(html: string): string {
  return mapMarkup(html, (markup) =>
    markup.replace(/<(script|link)\b[^>]*>/gi, (tag) => {
      if (/\bintegrity=/i.test(tag)) return tag;
      const url = tag.match(/\b(?:src|href)=(["'])([^"']*)\1/i)?.[2];
      const path = url ? pinnedPath(decodeAttr(url)) : null;
      if (!path) return tag;
      const attrs =
        ` integrity="sha256-${REVEAL_FILES[path]}" crossorigin="anonymous"`;
      return tag.endsWith("/>")
        ? `${tag.slice(0, -2).trimEnd()}${attrs}/>`
        : `${tag.slice(0, -1)}${attrs}>`;
    }));
}

/**
 * Inline every pinned reveal.js script and stylesheet, using `fetchFile` for
 * the verified bytes. References to unpinned CDN paths are left as links and
 * reported.
 */
export async function inlineReveal(
  html: string,
  fetchFile: (path: string) => Promise<Uint8Array>,
): Promise<{ html: string; problems: string[] }> {
  const problems: string[] = [];
  const decoder = new TextDecoder();
  const scriptRe = /<script\b([^>]*)\bsrc=(["'])([^"']*)\2([^>]*)>\s*<\/script\s*>/gi;
  const linkRe = /<link\b[^>]*>/gi;

  let out = "";
  let last = 0;
  // Script elements with a src have an empty body, so they are matched here
  // before mapMarkup would treat them as opaque.
  for (const m of html.matchAll(scriptRe)) {
    out += html.slice(last, m.index);
    const url = decodeAttr(m[3]);
    const path = pinnedPath(url);
    if (!path) {
      if (url.startsWith(`${REVEAL_CDN}/`)) {
        problems.push(`${url}: not a pinned reveal.js file, left as a link`);
      }
      out += m[0];
    } else {
      const js = decoder.decode(await fetchFile(path));
      const attrs = `${m[1]}${m[4]}`.replace(/\s+(integrity|crossorigin)=(["'])[^"']*\2/gi, "");
      out += `<script${attrs.trimEnd()}>\n${js.replace(/<\/script/gi, "<\\/script")}\n</script>`;
    }
    last = m.index + m[0].length;
  }
  out += html.slice(last);

  const final = await mapMarkupAsync(out, async (markup) =>
    await replaceAsync(markup, linkRe, async (m) => {
      const tag = m[0];
      if (!/\brel=["']?stylesheet/i.test(tag)) return tag;
      const url = tag.match(/\bhref=(["'])([^"']*)\1/i)?.[2];
      if (!url) return tag;
      const path = pinnedPath(decodeAttr(url));
      if (!path) {
        if (decodeAttr(url).startsWith(`${REVEAL_CDN}/`)) {
          problems.push(`${url}: not a pinned reveal.js file, left as a link`);
        }
        return tag;
      }
      const css = decoder.decode(await fetchFile(path));
      const id = tag.match(/\bid=(["'])([^"']*)\1/i);
      const idAttr = id ? ` id=${id[1]}${id[2]}${id[1]}` : "";
      return `<style${idAttr}>\n${css.replace(/<\/style/gi, "<\\/style")}\n</style>`;
    }));
  return { html: final, problems };
}

/**
 * Every resource the page still loads from outside itself: remote URLs and
 * local paths in resource attributes and stylesheet links. Links a viewer
 * clicks (`<a href>`) are not resources and are not listed.
 */
export function externalResources(html: string): string[] {
  const found = new Set<string>();
  mapMarkup(html, (markup) => {
    for (const tag of markup.matchAll(/<([a-z][a-z0-9-]*)\b[^>]*>/gi)) {
      const name = tag[1].toLowerCase();
      if (name === "a") continue;
      for (const attr of tag[0].matchAll(/\s([a-z-]+)=(["'])([^"']*)\2/gi)) {
        const key = attr[1].toLowerCase();
        const value = decodeAttr(attr[3]);
        const isResource = RESOURCE_ATTRS.includes(key) ||
          (key === "href" && name === "link" &&
            /\brel=["']?(stylesheet|icon|preload)/i.test(tag[0]));
        if (!isResource || value === "" || value.startsWith("data:")) continue;
        if (value.startsWith("#") || /^javascript:/i.test(value)) continue;
        if (
          (key === "data-background" || key === "data-background-image") &&
          !/[./]/.test(value)
        ) continue;
        found.add(value);
      }
    }
    return markup;
  });
  return [...found].sort();
}

/** One slide as rendered. */
export interface RenderedSlide {
  index: string;
  title: string;
  hasNotes: boolean;
}

function stripTags(s: string): string {
  return s.replace(/<[^>]*>/g, "").replace(/&nbsp;/g, " ").replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"')
    .replace(/&#39;|&rsquo;|&#8217;/g, "'").replace(/\s+/g, " ").trim();
}

/**
 * The slides of a rendered deck, in order: every `<section>` inside
 * `.slides` that contains no other section. A stack is numbered h.v, a lone
 * section h, the way reveal.js counts them.
 */
export function renderedSlides(html: string): RenderedSlide[] {
  const start = html.search(/<div\b[^>]*class=["'][^"']*\bslides\b[^"']*["'][^>]*>/i);
  if (start < 0) return [];
  const slides: RenderedSlide[] = [];
  const tokenRe = /<section\b[^>]*>|<\/section\s*>/gi;
  tokenRe.lastIndex = start;
  // Stack of open sections: where each began and whether it has children.
  const open: Array<{ from: number; hasChild: boolean; depth: number }> = [];
  let h = 0;
  const v: number[] = [];
  let body = html.slice(start);
  body = mapMarkup(body, (m) => m);
  void body;
  for (let m = tokenRe.exec(html); m; m = tokenRe.exec(html)) {
    if (m[0][1] !== "/") {
      if (open.length > 0) open[open.length - 1].hasChild = true;
      const depth = open.length;
      if (depth === 0) {
        h += 1;
        v[0] = 0;
      } else {
        v[0] += 1;
      }
      open.push({ from: m.index + m[0].length, hasChild: false, depth });
      continue;
    }
    const sec = open.pop();
    if (!sec) break;
    if (!sec.hasChild) {
      const inner = html.slice(sec.from, m.index);
      const heading = inner.match(/<h[1-6]\b[^>]*>([\s\S]*?)<\/h[1-6]>/i);
      slides.push({
        index: sec.depth === 0 ? String(h) : `${h}.${v[0]}`,
        title: heading ? stripTags(heading[1]) : "",
        hasNotes: /<aside\b[^>]*class=["'][^"']*\bnotes\b/i.test(inner),
      });
    }
    if (open.length === 0 && sec.depth === 0) {
      // Left the top-level section; keep scanning siblings.
    }
  }
  return slides;
}

