export function isLocalPath(ref: string): boolean {
  if (ref === "" || ref.startsWith("#") || ref.startsWith("//")) return false;
  if (/^file:/i.test(ref)) return true;
  return !/^[a-z][a-z0-9+.-]*:/i.test(ref);
}

