export function pinnedPath(url: string): string | null {
  const prefix = `${REVEAL_CDN}/`;
  if (!url.startsWith(prefix)) return null;
  const path = url.slice(prefix.length).split(/[?#]/)[0];
  return Object.hasOwn(REVEAL_FILES, path) ? path : null;
}

