/** Assign reveal.js indices: top level counts h, deeper levels count v. */
function indexSlides(
  raw: Array<Omit<OutlineSlide, "index">>,
): OutlineSlide[] {
  let h = 0;
  let v = 0;
  return raw.map((s) => {
    if (s.level <= 1) {
      h += 1;
      v = 0;
      return { ...s, index: String(h) };
    }
    if (h === 0) h = 1;
    v += 1;
    return { ...s, index: `${h}.${v}` };
  });
}

