    `<link rel="stylesheet" href="${REVEAL_CDN}/dist/reveal.css"/>`,
    `<script src="${REVEAL_CDN}/dist/reveal.js"></script>`,
    `<link rel="stylesheet" href="${REVEAL_CDN}/dist/theme/nope.css">`,
    '<script src="https://other.example/x.js"></script>',
