    `<link rel="stylesheet" href="${REVEAL_CDN}/dist/theme/black.css" id="theme"/>`,
    `<script src="${REVEAL_CDN}/dist/reveal.js" integrity="sha256-x" crossorigin="anonymous"></script>`,
    `<script src="${REVEAL_CDN}/dist/missing.js"></script>`,
