97	      throw new Error(
98	        `${cmd} is not installed or not on PATH. Install it, or set the global argument that names it.`,
99	      );
100	    }
101	    throw e;
102	  }
103	  return {
104	    code: out.code,
105	    stdout: out.stdout,
106	    stderr: new TextDecoder().decode(out.stderr),
107	  };
108	}
