114	/** Extract the HTML between the build script's markers. */
115	export function extractDeck(stdout: string): string {
116	  const begin = stdout.indexOf(`${DECK_BEGIN}\n`);
117	  const end = stdout.lastIndexOf(`\n${DECK_END}`);
118	  if (begin < 0 || end < begin) {
119	    throw new Error("org-re-reveal produced no deck (markers missing)");
120	  }
121	  return stdout.slice(begin + DECK_BEGIN.length + 1, end);
122	}
