282	/** Inline local images in Markdown source as data URIs. */
283	export async function inlineMarkdownImages(
284	  markdown: string,
285	  inline: (ref: string) => Promise<{ uri: string } | { problem: string }>,
286	  isLocal: (ref: string) => boolean,
287	): Promise<{ markdown: string; problems: string[] }> {
288	  const problems: string[] = [];
289	  const re = /(!\[[^\]]*\]\(\s*<?)([^)\s>]+)(>?(?:\s+"[^"]*")?\s*\))/g;
290	  const parts: string[] = [];
291	  let last = 0;
292	  for (const m of markdown.matchAll(re)) {
293	    parts.push(markdown.slice(last, m.index));
294	    if (isLocal(m[2])) {
295	      const r = await inline(m[2]);
296	      if ("uri" in r) parts.push(`${m[1]}${r.uri}${m[3]}`);
297	      else {
298	        problems.push(r.problem);
299	        parts.push(m[0]);
300	      }
301	    } else parts.push(m[0]);
302	    last = m.index + m[0].length;
303	  }
304	  parts.push(markdown.slice(last));
305	  return { markdown: parts.join(""), problems };
306	}
