  stdout: Uint8Array;
  stderr: string;
}

async function run(
  cmd: string,
  args: string[],
  opts: { signal?: AbortSignal; timeoutMs: number },
): Promise<ToolRun> {
  const timeout = AbortSignal.timeout(opts.timeoutMs);
