  const signal = opts.signal ? AbortSignal.any([opts.signal, timeout]) : timeout;
  let out: Deno.CommandOutput;
  try {
    out = await new Deno.Command(cmd, {
      args,
      stdin: "null",
      stdout: "piped",
      stderr: "piped",
      signal,
