230	/** Outline of a deck source, stored as `outline-<name>`. */
231	export type DeckOutline = z.infer<typeof OutlineSchema>;
232	/** Record of one PDF export, stored as `pdf-<name>`. */
233	export type DeckPdf = z.infer<typeof PdfSchema>;
234	
235	// =============================================================================
236	// Data names
237	// =============================================================================
238	
239	/** Data name of a deck's build record. */
240	export const deckResourceName = (name: string) => `deck-${name}`;
241	/** Data name of a deck's HTML file. */
242	export const deckHtmlName = (name: string) => `deck-${name}-html`;
243	/** Data name of a deck's PDF file. */
244	export const deckPdfName = (name: string) => `deck-${name}-pdf`;
245	/** Data name of a deck's outline. */
246	export const outlineResourceName = (name: string) => `outline-${name}`;
247	/** Data name of a deck's PDF record. */
248	export const pdfResourceName = (name: string) => `pdf-${name}`;
249	
250	// =============================================================================
251	// Context
252	// =============================================================================
253	
254	interface DataHandle {
255	  name: string;
256	  version?: number;
257	}
258	
259	interface Logger {
260	  info(msg: string, props?: Record<string, unknown>): void;
261	  warning(msg: string, props?: Record<string, unknown>): void;
262	}
263	
264	interface DeckContext {
265	  globalArgs: GlobalArgs;
266	  repoDir: string;
267	  signal?: AbortSignal;
268	  logger: Logger;
269	  writeResource(
270	    spec: string,
271	    name: string,
272	    data: Record<string, unknown>,
273	  ): Promise<DataHandle>;
274	  readResource(name: string): Promise<Record<string, unknown> | null>;
275	  createFileWriter(spec: string, name: string): {
276	    writeAll(content: Uint8Array): Promise<DataHandle>;
277	  };
278	}
279	
280	interface PdfContext extends DeckContext {
281	  modelType: unknown;
282	  modelId: string;
283	  dataRepository: {
284	    getContent(
285	      modelType: unknown,
286	      modelId: string,
287	      name: string,
288	      version?: number,
289	    ): Promise<Uint8Array | null>;
290	  };
291	}
292	
293	// =============================================================================
294	// Source loading
295	// =============================================================================
296	
297	interface LoadedSource {
298	  name: string;
299	  path: string | null;
300	  /** Directory relative references resolve against. */
301	  baseDir: string;
302	  text: string;
303	  format: Format;
304	  engine: Engine;
305	  sha256: string;
306	}
307	
308	async function loadSource(
309	  args: z.infer<typeof OutlineArgsSchema>,
310	  repoDir: string,
311	): Promise<LoadedSource> {
312	  if (args.content !== undefined) {
313	    const format = detectFormat(null, args.format);
314	    const bytes = new TextEncoder().encode(args.content);
315	    return {
316	      name: args.name!,
317	      path: null,
318	      baseDir: repoDir,
319	      text: args.content,
320	      format,
321	      engine: chooseEngine(format, args.engine),
322	      sha256: await sha256Hex(bytes),
323	    };
324	  }
325	  const given = args.source!;
326	  const absolute = given.startsWith("/") ? given : `${repoDir}/${given}`;
327	  let path: string;
328	  try {
329	    path = await Deno.realPath(absolute);
330	  } catch (e) {
331	    if (e instanceof Deno.errors.NotFound) {
332	      throw new Error(`Source not found: ${given}`);
333	    }
334	    throw e;
335	  }
336	  const bytes = await Deno.readFile(path);
337	  const format = detectFormat(path, args.format);
338	  return {
339	    name: args.name ?? deckNameFromPath(path),
340	    path,
341	    baseDir: path.slice(0, path.lastIndexOf("/")) || "/",
342	    text: new TextDecoder().decode(bytes),
343	    format,
344	    engine: chooseEngine(format, args.engine),
345	    sha256: await sha256Hex(bytes),
346	  };
347	}
348	
349	/**
350	 * Refuse to let one deck name hold two different sources. Two files called
351	 * `talk.org` in different directories would otherwise overwrite each
352	 * other's data.
353	 */
354	function assertSameSource(
355	  prior: Record<string, unknown> | null,
356	  src: LoadedSource,
357	): void {
358	  const priorPath = (prior?.source as { path?: string | null } | undefined)
359	    ?.path;
360	  if (prior === null || priorPath === undefined) return;
361	  if (priorPath !== src.path) {
362	    throw new Error(
363	      `Deck name "${src.name}" already belongs to ${
364	        priorPath ?? "inline content"
365	      }. Pass a different name for ${src.path ?? "this content"}.`,
366	    );
367	  }
368	}
369	
370	function cacheDirOf(g: GlobalArgs): string {
371	  return g.cacheDir ?? defaultCacheDir();
372	}
373	
374	async function withTempDir<T>(fn: (dir: string) => Promise<T>): Promise<T> {
375	  const dir = await Deno.makeTempDir({ prefix: "webframp-presentation-" });
376	  try {
377	    return await fn(dir);
378	  } finally {
379	    await Deno.remove(dir, { recursive: true }).catch(() => {});
380	  }
381	}
382	
383	/** Where the engine reads the source from: the file, or a temp copy of content. */
384	async function sourceFile(
385	  src: LoadedSource,
386	  dir: string,
387	): Promise<string> {
388	  if (src.path !== null) return src.path;
389	  const file = `${dir}/deck.${src.format === "org" ? "org" : "md"}`;
390	  await Deno.writeTextFile(file, src.text);
391	  return file;
392	}
393	
394	// =============================================================================
395	// Build
396	// =============================================================================
397	
398	interface Rendered {
399	  html: string;
400	  engineVersion: string | null;
401	  slides: Array<{ index: string; title: string; hasNotes: boolean }> | null;
402	  warnings: string[];
403	}
404	
405	async function render(
406	  src: LoadedSource,
407	  g: GlobalArgs,
408	  dir: string,
409	  signal?: AbortSignal,
410	): Promise<Rendered> {
411	  const file = await sourceFile(src, dir);
412	  switch (src.engine) {
413	    case "org-re-reveal": {
414	      const lispDir = await deps.ensureElisp(cacheDirOf(g), signal);
415	      const buildEl = `${dir}/build.el`;
416	      await Deno.writeTextFile(buildEl, BUILD_EL);
417	      const r = await renderOrg({
418	        emacs: g.emacs,
419	        buildEl,
420	        lispDir,
421	        source: file,
422	        theme: g.theme,
423	        signal,
424	      });
425	      const pin = ELISP_PINS.find((p) => p.file === "org-re-reveal.el");
426	      return {
427	        html: r.html,
428	        engineVersion: pin ? `org-re-reveal ${pin.version}` : null,
429	        slides: null,
430	        warnings: [],
431	      };
432	    }
433	    case "pandoc": {
434	      const r = await renderPandoc({
435	        pandoc: g.pandoc,
436	        source: file,
437	        theme: g.theme,
438	        workDir: dir,
439	        signal,
440	      });
441	      return {
442	        html: r.html,
443	        engineVersion: r.version ? `pandoc ${r.version}` : null,
444	        slides: null,
445	        warnings: [],
446	      };
447	    }
448	    case "reveal-markdown": {
449	      const parts = markdownParts(src.text);
450	      const images = await inlineMarkdownImages(
451	        parts.body,
452	        (ref) => dataUri(ref, src.baseDir),
453	        isLocalPath,
454	      );
455	      const theme = parts.theme ?? g.theme;
456	      const outline = outlineFor("reveal-markdown", src.text);
457	      return {
458	        html: renderRevealMarkdown({
459	          markdown: images.markdown,
460	          title: parts.title ?? outline.title ?? src.name,
461	          theme: REVEAL_THEMES.includes(theme) ? theme : g.theme,
462	        }),
463	        engineVersion: `reveal.js markdown plugin ${REVEAL_VERSION}`,
464	        // Rendered in the browser, so the outline is the slide list.
465	        slides: outline.slides.map((s) => ({
466	          index: s.index,
467	          title: s.title,
468	          hasNotes: s.notesWords > 0,
469	        })),
470	        warnings: [
471	          ...images.problems,
472	          ...(parts.theme !== null && !REVEAL_THEMES.includes(parts.theme)
473	            ? [
474	              `theme "${parts.theme}" is not a reveal.js theme; used ${g.theme}`,
475	            ]
476	            : []),
477	        ],
478	      };
479	    }
480	  }
481	}
482	
483	/** Theme a rendered deck loads, read from its theme stylesheet. */
484	function themeOf(html: string, fallback: string): string {
485	  for (const m of html.matchAll(/<link\b[^>]*>/gi)) {
486	    const href = m[0].match(/\shref=(["'])([^"']*)\1/i)?.[2] ?? "";
487	    const path = pinnedPath(href);
488	    if (path?.startsWith("dist/theme/")) {
489	      return path.slice("dist/theme/".length, -".css".length);
490	    }
491	  }
492	  return fallback;
493	}
494	
495	async function build(
496	  args: z.infer<typeof BuildArgsSchema>,
497	  context: DeckContext,
498	): Promise<{ dataHandles: DataHandle[] }> {
499	  const started = Date.now();
500	  const g = context.globalArgs;
501	  const src = await loadSource(args, context.repoDir);
502	  const prior = await context.readResource(deckResourceName(src.name));
503	  assertSameSource(prior, src);
504	
505	  const rendered = await withTempDir((dir) =>
506	    render(src, g, dir, context.signal)
507	  );
508	  const warnings = [...rendered.warnings];
509	
510	  const local = await inlineLocalFiles(rendered.html, src.baseDir);
511	  warnings.push(...local.problems);
512	  let html = local.html;
513	  // Read the theme before inlining replaces the stylesheet links.
514	  const theme = themeOf(html, g.theme);
515	
516	  if (args.selfContained) {
517	    const cacheDir = cacheDirOf(g);
518	    const inlined = await inlineReveal(
519	      html,
520	      (path) => deps.fetchRevealFile(cacheDir, path, context.signal),
521	    );
522	    html = inlined.html;
523	    warnings.push(...inlined.problems);
524	  } else {
525	    const pinned = await addIntegrity(html);
526	    html = pinned.html;
527	    warnings.push(...pinned.problems);
528	  }
529	
530	  const external = externalResources(html).filter((u) =>
531	    args.selfContained || pinnedPath(u) === null
532	  );
533	  if (args.selfContained) {
534	    for (const u of external) {
535	      warnings.push(`not self-contained: the deck still loads ${u}`);
536	    }
537	  }
538	  if (/\bRevealMath\b/.test(html)) {
539	    warnings.push(
540	      "the math plugin loads KaTeX or MathJax from a CDN when the deck opens",
541	    );
542	  }
543	
544	  const bytes = new TextEncoder().encode(html);
545	  const sha256 = await sha256Hex(bytes);
546	  const priorHtml = (prior as Deck | null)?.html;
547	  const unchanged = priorHtml?.sha256 === sha256;
548	
549	  const handles: DataHandle[] = [];
550	  let version: number;
551	  if (unchanged && priorHtml) {
552	    version = priorHtml.version;
553	  } else {
554	    const handle = await context.createFileWriter(
555	      "html",
556	      deckHtmlName(src.name),
557	    ).writeAll(bytes);
558	    handles.push(handle);
559	    version = handle.version ?? 1;
560	  }
561	
562	  const slides = rendered.slides ?? renderedSlides(html);
563	  const deck: Deck = {
564	    name: src.name,
565	    title: outlineFor(src.engine, src.text).title,
566	    engine: src.engine,
567	    engineVersion: rendered.engineVersion,
568	    source: { path: src.path, sha256: src.sha256, format: src.format },
569	    reveal: {
570	      version: REVEAL_VERSION,
571	      cdn: REVEAL_CDN,
572	      selfContained: args.selfContained,
573	    },
574	    theme,
575	    slides,
576	    slideCount: slides.length,
577	    html: { sha256, bytes: bytes.length, version },
578	    unchanged,
579	    external,
580	    warnings,
581	    durationMs: Date.now() - started,
582	    builtAt: new Date().toISOString(),
583	  };
584	  handles.push(
585	    await context.writeResource("deck", deckResourceName(src.name), deck),
586	  );
587	  for (const w of warnings) context.logger.warning(w, { deck: src.name });
588	  context.logger.info(
589	    unchanged
590	      ? "Deck {name} unchanged ({slides} slides); kept HTML version {version}"
591	      : "Built deck {name}: {slides} slides, {bytes} bytes, HTML version {version}",
592	    { name: src.name, slides: slides.length, bytes: bytes.length, version },
593	  );
594	  return { dataHandles: handles };
595	}
