1	// SPDX-License-Identifier: Apache-2.0
2	
3	/**
4	 * PDF export through Chromium's DevTools protocol.
5	 *
6	 * `chromium --print-to-pdf` cannot be used: it prints before reveal.js has
7	 * finished laying out its print view and produces one blank page. Driving
8	 * the browser over the protocol lets us wait until the layout settles.
9	 *
10	 * @module
11	 */
12	
13	/** The protocol calls the printer needs. */
14	export interface Cdp {
15	  send(
16	    method: string,
17	    params?: Record<string, unknown>,
18	  ): Promise<Record<string, unknown>>;
19	}
20	
21	/** How long to wait between layout checks, and how many equal counts in a row mean settled. */
22	const POLL_MS = 250;
23	const STABLE_POLLS = 4;
24	
25	const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
26	
27	/**
28	 * Settle with `p`, or reject once `deadline` (a `Date.now()` value) passes.
29	 * A browser whose page never answers must not hold the method forever.
30	 */
31	export function beforeDeadline<T>(
32	  p: Promise<T>,
33	  deadline: number,
34	  what: string,
35	): Promise<T> {
36	  let timer: ReturnType<typeof setTimeout> | undefined;
37	  const late = new Promise<never>((_, reject) => {
38	    timer = setTimeout(
39	      () => reject(new Error(`${what} did not finish before the deadline`)),
40	      Math.max(0, deadline - Date.now()),
41	    );
42	  });
43	  return Promise.race([p, late]).finally(() => clearTimeout(timer));
44	}
45	
46	/**
47	 * Open `url` (a deck with `?print-pdf`), wait until reveal.js's print layout
48	 * stops adding pages, and print it. Every protocol call must answer before
49	 * `deadline` (a `Date.now()` value). Returns the PDF and the page count.
50	 */
51	export async function printDeck(
52	  cdp: Cdp,
53	  url: string,
54	  deadline: number,
55	): Promise<{ pdf: Uint8Array; pages: number }> {
56	  const send = (method: string, params?: Record<string, unknown>) =>
57	    beforeDeadline(cdp.send(method, params), deadline, method);
58	  await send("Page.enable");
59	  await send("Page.navigate", { url });
60	  let last = -1;
61	  let stable = 0;
62	  while (stable < STABLE_POLLS) {
63	    if (Date.now() + POLL_MS > deadline) {
64	      throw new Error(
65	        `reveal.js print layout did not settle in time (last page count ${last}). A deck that loads reveal.js from the CDN needs network access.`,
66	      );
67	    }
68	    await sleep(POLL_MS);
69	    const r = await send("Runtime.evaluate", {
70	      expression: "document.querySelectorAll('.pdf-page').length",
71	      returnByValue: true,
72	    });
73	    const n = Number(
74	      (r.result as { value?: unknown } | undefined)?.value ?? 0,
75	    );
76	    stable = n > 0 && n === last ? stable + 1 : 0;
77	    last = n;
78	  }
79	  const printed = await send("Page.printToPDF", {
80	    preferCSSPageSize: true,
81	    printBackground: true,
82	  });
83	  const data = printed.data;
84	  if (typeof data !== "string") throw new Error("Chromium returned no PDF");
85	  const bin = atob(data);
86	  const pdf = new Uint8Array(bin.length);
87	  for (let i = 0; i < bin.length; i++) pdf[i] = bin.charCodeAt(i);
88	  return { pdf, pages: last };
89	}
90	
91	/** A protocol session over a WebSocket. */
92	export function cdpOverWebSocket(ws: WebSocket): Cdp {
93	  let id = 0;
94	  const pending = new Map<
95	    number,
96	    {
97	      resolve: (v: Record<string, unknown>) => void;
98	      reject: (e: Error) => void;
99	    }
100	  >();
101	  ws.onmessage = (e) => {
102	    const msg = JSON.parse(String(e.data));
103	    const p = typeof msg.id === "number" ? pending.get(msg.id) : undefined;
104	    if (!p) return;
105	    pending.delete(msg.id);
106	    if (msg.error) {
107	      p.reject(new Error(`DevTools ${msg.error.message ?? "error"}`));
108	    } else p.resolve(msg.result ?? {});
109	  };
110	  ws.onclose = () => {
111	    for (const p of pending.values()) {
112	      p.reject(new Error("DevTools connection closed"));
113	    }
114	    pending.clear();
115	  };
116	  return {
117	    send(method, params = {}) {
118	      return new Promise((resolve, reject) => {
119	        const n = ++id;
120	        pending.set(n, { resolve, reject });
121	        ws.send(JSON.stringify({ id: n, method, params }));
122	      });
123	    },
124	  };
125	}
126	
127	/**
128	 * Launch headless Chromium on a private profile, print the deck at `url`,
129	 * and shut the browser down whatever happens. Everything, startup included,
130	 * must finish within `timeoutMs`.
131	 */
132	export async function exportPdf(opts: {
133	  chromium: string;
134	  url: string;
135	  profileDir: string;
136	  timeoutMs: number;
137	  noSandbox: boolean;
138	}): Promise<{ pdf: Uint8Array; pages: number }> {
139	  const deadline = Date.now() + opts.timeoutMs;
140	  const args = [
141	    "--headless=new",
142	    "--disable-gpu",
143	    "--no-first-run",
144	    "--no-default-browser-check",
145	    "--remote-debugging-port=0",
146	    `--user-data-dir=${opts.profileDir}`,
147	    ...(opts.noSandbox ? ["--no-sandbox"] : []),
148	    "about:blank",
149	  ];
