  try {
    child = new Deno.Command(opts.chromium, {
      args,
      stdin: "null",
      stdout: "null",
      stderr: "piped",
    }).spawn();
  } catch (e) {
    if (e instanceof Deno.errors.NotFound) {
      throw new Error(
        `${opts.chromium} is not installed or not on PATH. Set the chromium global argument.`,
      );
    }
    throw e;
  }
