        const path = pinnedPath(url);
        if (!path) {
          problems.push(`${url}: not a pinned reveal.js file`);
          return tag;
        }
        const extra = ` integrity="sha256-${
          REVEAL_FILES[path]
        }" crossorigin="anonymous"`;
        return tag.endsWith("/>")
          ? `${tag.slice(0, -2).trimEnd()}${extra}/>`
