        const tag = m[0];
        const element = m[1].toLowerCase();
        if (element === "link" && isStylesheet(tag)) {
          const href = attr(tag, "href");
          if (href === null || !isLocalPath(href)) return tag;
          const r = await inliner.stylesheet(href, baseDir);
          if ("problem" in r) {
